class Solution {
    public int getLucky(String s, int k) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            sb.append(c - 'a' + 1);
        }
        String numStr = sb.toString();
        int result = 0;
        for (int i = 0; i < k; i++) {
            result = 0;
            for (char c : numStr.toCharArray()) {
                result += c - '0';
            }
            numStr = String.valueOf(result);
        }
        return result;
    }
}
